let seedPromise: Promise<void> | null = null;

export function seedDatabase(): Promise<void> {
  if (!seedPromise) {
    seedPromise = performSeed();
  }
  return seedPromise;
}

export function resetSeedState(): void {
  seedPromise = null;
}

async function performSeed(): Promise<void> {
  const count = await db.monsterTemplates.count();
  if (count > 0) {
    // Rebuild monsterTemplates to sync new monsters
    await db.monsterTemplates.clear();
    await db.monsterTemplates.bulkAdd(MONSTER_SEEDS as any);

    // Rebuild dropTables to fix legacy duplication
    await db.dropTables.clear();
    await db.dropTables.bulkAdd(DROP_TABLE_SEEDS as any);

    // Sync equipment templates: update existing, add missing
    const existingTemplates = await db.equipmentTemplates.toArray();
    const existingNames = new Set(existingTemplates.map(t => t.name));
    const seedMap = new Map<string, typeof EQUIPMENT_SEEDS[number]>();
    for (const seed of EQUIPMENT_SEEDS) {
      seedMap.set(seed.name, seed);
    }

    // Add new templates that don't exist yet (craft recipes)
    const newTemplates = EQUIPMENT_SEEDS.filter(s => !existingNames.has(s.name));
    if (newTemplates.length > 0) {
      await db.equipmentTemplates.bulkAdd(newTemplates as any);
    }

    // Update all existing templates with latest data
    for (const seed of EQUIPMENT_SEEDS) {
      if (existingNames.has(seed.name)) {
        await db.equipmentTemplates.where('name').equals(seed.name).modify({
          attackSuccess: seed.attackSuccess,
          extraAttack: seed.extraAttack,
          magicAttack: (seed as any).magicAttack,
          smallMonsterDamage: seed.smallMonsterDamage,
          largeMonsterDamage: seed.largeMonsterDamage,
          bonusHp: (seed as any).bonusHp,
          bonusMp: (seed as any).bonusMp,
          hpRegen: (seed as any).hpRegen,
          mpRegen: (seed as any).mpRegen,
          bonusWeight: (seed as any).bonusWeight,
          bonusStats: (seed as any).bonusStats,
          blockRate: (seed as any).blockRate,
          stability: (seed as any).stability,
          weight: (seed as any).weight,
          acquireType: (seed as any).acquireType,
          craftTier: (seed as any).craftTier,
          craftGold: (seed as any).craftGold,
          craftMaterials: (seed as any).craftMaterials,
          canBreak: (seed as any).canBreak,
          material: (seed as any).material,
          requiredClass: (seed as any).requiredClass,
        });
      }
    }
    // Patch existing equipment instances with missing fields
    await db.equipmentInstances.toCollection().modify((instance: any) => {
      const seed = seedMap.get(instance.name as string);
      if (seed) {
        if (instance.attackSuccess == null) instance.attackSuccess = seed.attackSuccess;
        if (instance.extraAttack == null) instance.extraAttack = seed.extraAttack;
        if ((seed as any).magicAttack && instance.magicAttack == null) instance.magicAttack = (seed as any).magicAttack;
        if ((seed as any).bonusHp && instance.bonusHp == null) instance.bonusHp = (seed as any).bonusHp;
        if ((seed as any).bonusMp && instance.bonusMp == null) instance.bonusMp = (seed as any).bonusMp;
        if ((seed as any).hpRegen && instance.hpRegen == null) instance.hpRegen = (seed as any).hpRegen;
        if ((seed as any).mpRegen && instance.mpRegen == null) instance.mpRegen = (seed as any).mpRegen;
        if ((seed as any).bonusWeight && instance.bonusWeight == null) instance.bonusWeight = (seed as any).bonusWeight;
        if ((seed as any).bonusStats && instance.bonusStats == null) instance.bonusStats = (seed as any).bonusStats;
        if ((seed as any).blockRate && instance.blockRate == null) instance.blockRate = (seed as any).blockRate;
        if ((seed as any).stability != null) instance.stability = (seed as any).stability;
        if ((seed as any).weight && instance.weight == null) instance.weight = (seed as any).weight;
      }
    });
    return;
  }

  await db.monsterTemplates.bulkAdd(MONSTER_SEEDS as any);
  await db.equipmentTemplates.bulkAdd(EQUIPMENT_SEEDS as any);
  await db.dropTables.bulkAdd(DROP_TABLE_SEEDS as any);
}
